import { ChevronDownSmallIcon } from "@egov3/graphics/Basic/ChevronDownSmall";
import { ChevronLeftIcon } from "@egov3/graphics/Basic/ChevronLeft";
import { ChevronRightIcon } from "@egov3/graphics/Basic/ChevronRight";
import { CloseIcon } from "@egov3/graphics/General/Close";

import type { TPeriodKeys } from "~interfaces/Calendar";
import type { ILangProps } from "~interfaces/common";

import { Typography } from "~baseComponents";
import { PERIOD_KEYS } from "~constants/calendar";
import { i18n } from "~constants/i18n";
import { useCalendar } from "~customHooks/useCalendar";
import { getMonthNameProper } from "~utils/date/getMonthNameProper";
import { joinClasses } from "~utils/joinClasses";

import styles from "./CalendarBody.module.css";

export interface ICalendarBodyProps extends ILangProps {
  month?: number;
  year?: number;
  selectedDate?: Date | null;
  rangeStart?: Date | null;
  rangeEnd?: Date | null;
  minDate?: Date | null;
  maxDate?: Date | null;
  maxPeriodMonths?: number | null;
  selectedPeriodInterval?: TPeriodKeys;
  onDayClick?: (date: Date) => void;
  onMonthChange?: (date: Date) => void;
}

export const CalendarBody = ({
  lang,
  month = new Date().getMonth(),
  year = new Date().getFullYear(),
  selectedDate = null,
  rangeStart = null,
  rangeEnd = null,
  minDate = null,
  maxDate = null,
  maxPeriodMonths = null,
  selectedPeriodInterval = PERIOD_KEYS.from,
  onDayClick,
  onMonthChange,
}: ICalendarBodyProps) => {
  const {
    days,
    years,
    visibleMonth,
    visibleYear,
    isYearPickerOpen,
    isNextMonthDisabled,
    isPrevMonthDisabled,
    setIsYearPickerOpen,
    yearListRef,
    changeMonth,
    pickYear,
  } = useCalendar({
    month,
    year,
    selectedDate,
    selectedPeriodInterval,
    rangeStart,
    rangeEnd,
    minDate,
    maxDate,
    maxPeriodMonths,
    onMonthChange,
  });
  const monthName = getMonthNameProper(visibleMonth, lang);
  const weekDays = i18n.Calendar.WeekDays[lang];

  return (
    <div className={styles.wrapper} data-testid="CalendarBody">
      <div className={styles.header} data-testid="CalendarBody_HEADER">
        <div
          className={styles.monthYear}
          data-testid="Calendar_MONTH_YEAR_LABEL"
        >
          <Typography
            tag="span"
            fontClass="body1Medium"
            data-testid="CalendarBody_MONTH_YEAR"
          >
            {monthName}
          </Typography>
          <button
            className={styles.yearButton}
            type="button"
            onClick={() => {
              setIsYearPickerOpen(true);
            }}
            data-testid="Calendar_CHOOSE_YEAR_BTN"
          >
            <Typography
              tag="span"
              fontClass="body1Medium"
              data-testid="Calendar_CURRENT_YEAR"
            >
              {visibleYear}
            </Typography>
            <ChevronDownSmallIcon
              width="24px"
              height="24px"
              fill="var(--icon-accent-color)"
            />
          </button>
        </div>
        {isYearPickerOpen ? (
          <button
            type="button"
            onClick={() => {
              setIsYearPickerOpen(false);
            }}
            data-testid="Calendar_CLOSE_YEAR_PICKER_BTN"
          >
            <CloseIcon width="24px" height="24px" />
          </button>
        ) : (
          <>
            <button
              className={styles.navButton}
              type="button"
              onClick={() => {
                changeMonth(-1);
              }}
              data-testid="Calendar_PREV_MONTH_BTN"
              disabled={isPrevMonthDisabled}
            >
              <ChevronLeftIcon
                width="24px"
                height="24px"
                fill="var(--icon-accent-color)"
              />
            </button>
            <button
              className={styles.navButton}
              type="button"
              onClick={() => {
                changeMonth(1);
              }}
              data-testid="Calendar_NEXT_MONTH_BTN"
              disabled={isNextMonthDisabled}
            >
              <ChevronRightIcon
                width="24px"
                height="24px"
                fill="var(--icon-accent-color)"
              />
            </button>
          </>
        )}
      </div>
      {isYearPickerOpen ? (
        <div
          ref={yearListRef}
          className={styles.years}
          data-testid="Calendar_YEARS_LIST"
        >
          {years.map((yearItem) => (
            <button
              key={yearItem}
              data-testid={`CalendarBody_YEAR_${yearItem}`}
              data-year={yearItem}
              type="button"
              className={joinClasses(
                styles.yearItem,
                yearItem === visibleYear && styles.yearItemSelected,
              )}
              onClick={() => {
                pickYear(yearItem);
              }}
            >
              <Typography tag="span" fontClass="body1Medium">
                {yearItem}
              </Typography>
            </button>
          ))}
        </div>
      ) : (
        <>
          <div className={styles.weekDays} data-testid="Calendar_WEEK_DAYS">
            {weekDays.map((day) => (
              <Typography
                tag="span"
                fontClass="body2Medium"
                key={day}
                className={styles.weekDay}
                data-testid={`CalendarBody_WEEK_DAY_${day}`}
              >
                {day}
              </Typography>
            ))}
          </div>
          <div className={styles.grid} data-testid="Calendar_DAYS_GRID">
            {days.map((cell) => {
              return (
                <button
                  key={cell.date.toISOString()}
                  type="button"
                  className={joinClasses(
                    styles.day,
                    !cell.isCurrentMonth && styles.hiddenDay,
                    cell.isDisabled && styles.disabledDay,
                    cell.isToday && styles.today,
                    cell.isSelected && styles.selected,
                  )}
                  onClick={() => {
                    onDayClick?.(cell.date);
                  }}
                  disabled={!cell.isCurrentMonth || cell.isDisabled}
                  data-testid={`CalendarBody_DAY_${cell.date.toISOString().slice(0, 10)}`}
                >
                  {cell.isCurrentMonth && (
                    <Typography
                      tag="span"
                      fontClass="body2Medium"
                      data-testid={`CalendarBody_DAY_${cell.date.toISOString().slice(0, 10)}_LABEL`}
                    >
                      {cell.day}
                    </Typography>
                  )}
                </button>
              );
            })}
          </div>
        </>
      )}
    </div>
  );
};
